{
  "IP": "neorv32_debug_auth",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Debug authentication-valid state",
      "Unit": "neorv32_debug_auth",
      "Information": "The state records whether debug authentication is currently valid, which the surrounding debug system depends on to recognize an authenticated session.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality no: the RTL exposes only an authentication status at valid_o, not a secret credential (66). Integrity yes: wdata_i(0) can directly modify authenticated_q when we_i is asserted (56-57), and enable_i can clear it (54-55). Availability yes: clearing authenticated_q drives valid_o low, withholding the authentication result needed by the debug system (55,66). Undermined Expected Behavior no: the RTL shows no privileged-mode, override, bypass or test-packet behavior acting on this state.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could assert we_i with wdata_i(0) set to one to forge authentication, or drive enable_i low to clear the state and deny debug access.",
      "Enters Through": [
        "wdata_i"
      ],
      "Leaves Through": [
        "valid_o"
      ],
      "Entry Lines": [
        57
      ],
      "Held Lines": [
        52,
        55,
        57
      ],
      "Exit Lines": [
        66
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Authentication-state write command",
      "Unit": "neorv32_debug_auth",
      "Information": "The write command determines whether the supplied write value may update the authentication-valid state; it has no output because the RTL only consumes it as the write condition.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality no: we_i is a control command rather than secret information. Integrity yes: we_i authorizes an external write that changes the security-relevant authentication state (56-57). Availability yes: holding we_i low blocks the required authentication-state write (56). Undermined Expected Behavior no: no separate override, bypass or privileged integration behavior is shown.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could suppress we_i to prevent authentication or assert it with attacker-controlled write data to alter authenticated_q.",
      "Enters Through": [
        "we_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        56
      ],
      "Held Lines": [
        56
      ],
      "Exit Lines": []
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Authentication enable control",
      "Unit": "neorv32_debug_auth",
      "Information": "The enable control determines whether the authentication state can be retained or is cleared, affecting whether the debug authentication function remains usable.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality no: enable_i is a control input and the RTL does not treat it as secret information. Integrity yes: enable_i controls clearing of the authentication-valid state (54-55). Availability yes: forcing enable_i low clears authenticated_q and causes valid_o to remain low (54-55,66). Undermined Expected Behavior no: the RTL shows no distinct privileged-mode, override or bypass behavior.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could force enable_i low to clear authenticated_q and keep valid_o deasserted, disabling authenticated debug operation.",
      "Enters Through": [
        "enable_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        54
      ],
      "Held Lines": [],
      "Exit Lines": []
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Authentication write value",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "C1",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Read access command",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "re_i is never read or used by the RTL (26), so it has no demonstrated security-relevant use or violation mechanism."
    },
    {
      "Candidate Name": "Authentication readback data",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "rdata_o is assigned only the constant zero value (69), so it carries no security-relevant state or data."
    },
    {
      "Candidate Name": "Busy status",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "busy_o is tied to a constant zero (63), so it does not report or control a meaningful design state."
    },
    {
      "Candidate Name": "Clock timing",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "clk_i only times authenticated_q and is excluded as a clock rather than being information protected under these questions (49,53)."
    },
    {
      "Candidate Name": "Reset control",
      "Candidate Unit": "neorv32_debug_auth",
      "Merged Into": "",
      "Why Not Kept": "rstn_i only resets authenticated_q and is excluded by the clocks-and-resets rule (51)."
    }
  ],
  "Notes": []
}
